// WorkerStatus Derived worker state, reconciled from the worker pod's lifecycle status
// and the live job-queue view.
// - `RUNNING`      — actively processing a job
// - `IDLE`         — ready and polling for jobs
// - `INITIALIZING` — starting up, not yet ready
// - `THROTTLED`    — waiting on compute capacity
// - `UNHEALTHY`    — failing health checks
type WorkerStatus string

// WorkerSummary Histogram of the returned workers by status. The per-status counts are a
// roll-up of the `workers` array, so `running + idle + initializing +
// throttled + unhealthy == total == len(workers)`.
type WorkerSummary struct {
	// Idle Ready workers polling for jobs.
	//
	// Examples: 1
	Idle int `json:"idle"`

	// Initializing Workers starting up, not yet ready.
	//
	// Examples: 0
	Initializing int `json:"initializing"`

	// Running Workers actively processing a job.
	//
	// Examples: 2
	Running int `json:"running"`

	// Throttled Workers waiting on compute capacity.
	//
	// Examples: 0
	Throttled int `json:"throttled"`

	// Total All workers currently allocated to the endpoint.
	//
	// Examples: 3
	Total int `json:"total"`

	// Unhealthy Workers failing health checks.
	//
	// Examples: 0
	Unhealthy int `json:"unhealthy"`
}

